import java.util.Comparator;
import java.util.List;
import java.util.function.Consumer;

interface Bin<T> {                           // no declaration-site variance in Java
    void drop(T item);
}

class Bins {
    // every consumer parameter must remember ? super
    static <T> void dropAll(List<? extends T> items, Bin<? super T> bin) {
        for (T item : items) bin.drop(item);
    }

    static <T> T highest(List<? extends T> items, Comparator<? super T> order) {
        T best = items.get(0);
        for (T item : items) if (order.compare(item, best) > 0) best = item;
        return best;
    }

    static <E> void listen(Consumer<? super E> listener) { /* store it */ }
}

