interface Bin<in T> {                        // say it once
    fun drop(item: T)
}

// Bin and List carry their variance, so these signatures stay plain
fun <T> dropAll(items: List<T>, bin: Bin<T>) {
    for (item in items) bin.drop(item)
}

// java.util.Comparator is a Java interface: invariant, so project it here
fun <T> highest(items: List<T>, order: Comparator<in T>): T {
    var best = items[0]
    for (item in items) if (order.compare(item, best) > 0) best = item
    return best
}

