class DeliveryBell<E> {
    private val listeners = ArrayList<(E) -> Unit>()

    fun listen(listener: (E) -> Unit) { listeners.add(listener) }

    fun ring(item: E): Int {
        for (l in listeners) l(item)
        return listeners.size
    }
}

