class DeliveryBell<E> {
    private final List<Consumer<? super E>> listeners = new ArrayList<>();

    void listen(Consumer<? super E> listener) { listeners.add(listener); }

    int ring(E item) {
        for (Consumer<? super E> l : listeners) l.accept(item);
        return listeners.size();
    }
}

var apples = new DeliveryBell<Apple>();
apples.listen(appleSign);
apples.listen(stockCount);              // fine thanks to ? super E
apples.ring(new Apple("Gala", 180));    // 2

var allFruit = new DeliveryBell<Fruit>();
allFruit.listen(appleSign);
// error: incompatible types: Consumer<Apple> cannot be converted to Consumer<? super Fruit>
